effect.shader:
float hash(float x) { return fract(sin(x * 91.3458) * 47453.5453); }

void main() {
    vec2 uv = acScreenNorm;
    float band = floor(uv.y * bandCount);
    float seed = band + floor(acTime * speed * bandCount * 0.1);
    float r = hash(seed);
    float ativo = step(1.0 - intensity, r);
    float shift = (hash(seed + 7.0) - 0.5) * intensity * 0.2 * ativo;

    vec2 uvS = vec2(uv.x + shift, uv.y);
    float rshift = rgbShift * ativo / acResolution.x;

    float cr = texture(inputImg, uvS + vec2(rshift, 0.0)).r;
    vec4 cg = texture(inputImg, uvS);
    float cb = texture(inputImg, uvS - vec2(rshift, 0.0)).b;

    fragColor = vec4(cr, cg.g, cb, cg.a);
}
